// POST /v1/memory — stateful agent memory: store, search, forget. Semantic
// recall over the caller's own namespaces with no vector DB to run — the
// STATEFUL endpoint (memories live here between calls), which is exactly what
// a prompt can't replicate. Cheap per operation.

import { z } from "@compound/validation";
import { serveEndpoint } from "@/lib/platform/endpoint";
import { embedText } from "@/lib/platform/gemini-media";
import { adminSupabase } from "@/lib/supabase/admin";
import { RATES } from "@/lib/platform/constants";

export const runtime = "nodejs";
export const maxDuration = 30;

const Body = z
  .object({
    op: z.enum(["store", "search", "forget"]),
    namespace: z.string().min(1).max(120).optional(),
    content: z.string().min(1).max(20_000).optional(),
    metadata: z.record(z.string(), z.unknown()).optional(),
    query: z.string().min(1).max(2_000).optional(),
    limit: z.number().int().min(1).max(25).optional(),
    id: z.string().uuid().optional(),
  })
  .refine((b) => b.op !== "store" || !!b.content, { message: "store requires content." })
  .refine((b) => b.op !== "search" || !!b.query, { message: "search requires query." })
  .refine((b) => b.op !== "forget" || !!(b.id || b.namespace), {
    message: "forget requires id (one memory) or namespace (wipe it).",
  });

interface MemoryRow {
  id: string;
  content: string;
  metadata: Record<string, unknown>;
  created_at: string;
  score: number;
}

export function POST(req: Request) {
  return serveEndpoint<z.infer<typeof Body>, Record<string, unknown>>(req, {
    endpoint: "memory",
    rate: RATES.memory,
    schema: Body,
    execute: async (input, auth) => {
      const namespace = input.namespace ?? "default";
      const admin = adminSupabase();

      if (input.op === "store") {
        const embedding = await embedText(input.content!);
        if (!embedding) {
          return {
            ok: false as const,
            code: "inference_unavailable" as const,
            message: "Embedding is temporarily unavailable.",
          };
        }
        const { data, error } = await admin
          .from("compound_agent_memories")
          .insert({
            account_id: auth.accountId,
            namespace,
            content: input.content,
            metadata: input.metadata ?? {},
            embedding: JSON.stringify(embedding),
          })
          .select("id")
          .single();
        if (error || !data) {
          return { ok: false as const, code: "unprocessable" as const, message: "Could not store the memory." };
        }
        return {
          ok: true,
          data: { op: "store", id: data.id as string },
          model: "gemini-embedding-001",
          meta: { namespace },
        };
      }

      if (input.op === "search") {
        const embedding = await embedText(input.query!);
        if (!embedding) {
          return {
            ok: false as const,
            code: "inference_unavailable" as const,
            message: "Embedding is temporarily unavailable.",
          };
        }
        const { data, error } = await admin.rpc("compound_memory_search", {
          p_account: auth.accountId,
          p_namespace: namespace,
          p_embedding: JSON.stringify(embedding),
          p_limit: input.limit ?? 5,
        });
        if (error) {
          return { ok: false as const, code: "unprocessable" as const, message: "Search failed." };
        }
        const rows = (data ?? []) as MemoryRow[];
        return {
          ok: true,
          data: {
            op: "search",
            results: rows.map((r) => ({
              id: r.id,
              content: r.content,
              score: Math.round(r.score * 1000) / 1000,
              metadata: r.metadata ?? {},
              createdAt: r.created_at,
            })),
          },
          model: "gemini-embedding-001",
          meta: { namespace, results: rows.length },
        };
      }

      // forget: by id, or wipe the namespace.
      let del = admin.from("compound_agent_memories").delete({ count: "exact" }).eq("account_id", auth.accountId);
      del = input.id ? del.eq("id", input.id) : del.eq("namespace", namespace);
      const { count, error } = await del;
      if (error) {
        return { ok: false as const, code: "unprocessable" as const, message: "Delete failed." };
      }
      return {
        ok: true,
        data: { op: "forget", deleted: count ?? 0 },
        meta: { namespace },
      };
    },
  });
}
